/** @generated — 원본 legacy-html/legal/copyright.html */
export const title = "PING 지식재산권 및 저작권 보호 정책";
export const articleHtml = "<h1>PING 지식재산권 및 저작권 보호 정책</h1>\n\n    <div class=\"chapter-title\">제 1 장 총 칙</div>\n\n    <div class=\"section\">\n        <h2>제 1 조 (목적)</h2>\n        <p>본 정책은 PING(이하 \"회사\")이 제공하는 모바일 부고 알림 및 조문 관리 플랫폼(이하 \"서비스\")과 관련된 저작권, 특허권, 상표권 등 지식재산권(Intellectual Property Rights)을 보호하고, 제3자의 무단 도용 및 모방 행위에 대한 법적 대응 기준을 규정함을 목적으로 합니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 2 조 (권리의 정의)</h2>\n        <p>① \"지식재산권\"이라 함은 회사가 창작한 소스코드, UI/UX 디자인, 데이터베이스 구조, 비즈니스 모델(BM), 콘텐츠 등 법적으로 보호받는 모든 권리를 말합니다.</p>\n        <p>② \"모방 행위\"라 함은 회사의 서비스와 실질적으로 유사한 구조, 기능, 디자인을 차용하여 혼동을 일으키거나 회사의 성과를 무단으로 사용하는 행위를 의미합니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 3 조 (권리의 귀속)</h2>\n        <p>서비스와 관련된 모든 지식재산권은 회사에 전적으로 귀속됩니다. 이는 대한민국 「저작권법」, 「특허법」, 「부정경쟁방지 및 영업비밀보호에 관한 법률」 및 국제 저작권 협약에 의해 보호됩니다.</p>\n    </div>\n\n    <div class=\"chapter-title\">제 2 장 권리의 등록 및 보호 범위</div>\n\n    <div class=\"section\">\n        <h2>제 4 조 (저작권의 등록)</h2>\n        <p>① 본 서비스의 핵심이 되는 소스코드, 애플리케이션 디자인, 부고장 템플릿 등은 대한민국 「저작권법」 제53조에 따라 한국저작권위원회에 프로그램 저작물 및 편집 저작물로 등록되었습니다.</p>\n        <p>② 이에 따라, 회사의 허락 없이 해당 저작물을 복제, 배포, 개작, 전송하는 행위는 5년 이하의 징역 또는 5천만 원 이하의 벌금형에 처해질 수 있습니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 5 조 (특허 출원 및 기술 보호)</h2>\n        <p>① 회사가 제공하는 '모바일 부고 알림 및 조문객 데이터 처리 시스템'의 핵심 기술과 비즈니스 프로세스는 특허청에 임시명세서(Provisional Specification)를 통해 출원되어 특허법상의 보호를 받고 있습니다.</p>\n        <p>② 출원된 기술 내용과 동일하거나 균등한 범위 내에서 서비스를 구현하는 것은 회사의 특허권을 침해하는 행위로 간주됩니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 6 조 (보호 대상의 범위)</h2>\n        <p>본 정책에 의해 보호받는 대상은 다음 각 호를 포함합니다.</p>\n        <p>웹사이트 및 애플리케이션의 소스코드 (HTML, CSS, JavaScript, Server-side Code 등)</p>\n        <p>사용자 인터페이스(UI) 및 사용자 경험(UX)의 독창적인 배치와 흐름</p>\n        <p>부고장 템플릿의 디자인, 레이아웃, 문구 구성</p>\n        <p>데이터베이스의 구조 및 알고리즘</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 7 조 (상표권)</h2>\n        <p>'PING' 및 서비스 로고, 심볼, 슬로건은 회사의 등록 상표이거나 출원 중인 상표로서, 회사의 사전 서면 동의 없이 이를 무단으로 사용하여 타인에게 혼동을 주는 행위를 금지합니다.</p>\n    </div>\n\n    <div class=\"chapter-title\">제 3 장 금지 행위 및 침해의 기준</div>\n\n    <div class=\"section\">\n        <h2>제 8 조 (무단 복제 및 전재 금지)</h2>\n        <p>누구든지 회사의 사전 승낙 없이 서비스의 화면, 이미지, 텍스트, 데이터 등을 캡처, 복사, 크롤링(Crawling) 등의 방법으로 수집하여 상업적으로 이용하거나 제3자에게 제공해서는 안 됩니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 9 조 (역설계 및 소스코드 추출 금지)</h2>\n        <p>이용자 및 제3자는 서비스의 소프트웨어를 리버스 엔지니어링(Reverse Engineering), 디컴파일(Decompile), 디스어셈블(Disassemble) 하거나 기타 일체의 가공 행위를 통해 소스코드를 추출하려는 시도를 해서는 안 됩니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 10 조 (동일·유사 서비스 제공 금지)</h2>\n        <p>① 누구든지 회사가 특허 출원 및 저작권 등록을 통해 구축한 서비스와 동일하거나 실질적으로 유사한 구조(Structure)와 기능(Function)을 가진 서비스를 제공하는 자는 관련 법에 저촉을 받습니다.</p>\n        <p>② 특히, 회사의 고유한 '부고 알림 프로세스'와 '조문 관리 UI'를 그대로 모방하여 경쟁 서비스를 출시하는 경우, 이는 부정경쟁행위로 간주되어 즉각적인 서비스 중단 가처분 신청의 대상이 됩니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 11 조 (프레임 링크 및 심층 링크 제한)</h2>\n        <p>타 사이트에서 본 서비스의 화면을 프레임(Frame) 내에 구성하거나, 메인 페이지를 거치지 않고 특정 콘텐츠로 직접 연결되는 심층 링크(Deep Link)를 사용하여 마치 자신의 서비스인 것처럼 오인하게 하는 행위를 금지합니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 12 조 (부정경쟁행위의 금지)</h2>\n        <p>「부정경쟁방지 및 영업비밀보호에 관한 법률」 제2조 제1호 (카)목에 의거하여, 타인의 상당한 투자나 노력으로 만들어진 성과 등을 공정한 상거래 관행이나 경쟁 질서에 반하는 방법으로 자신의 영업을 위하여 무단으로 사용하는 행위를 엄격히 금지합니다.</p>\n    </div>\n\n    <div class=\"chapter-title\">제 4 장 침해에 대한 법적 대응</div>\n\n    <div class=\"section\">\n        <h2>제 13 조 (침해 행위의 감시)</h2>\n        <p>회사는 전담 법무팀 및 자동화된 모니터링 시스템을 통해 24시간 온·오프라인상에서의 저작권 침해 및 유사 서비스 출시 여부를 감시하고 있습니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 14 조 (경고 및 시정 조치)</h2>\n        <p>지식재산권 침해 사실이 확인될 경우, 회사는 침해자에게 즉시 침해 행위의 중지, 침해 물건(서버 내 데이터, 앱 등)의 폐기, 사과문 게시 등을 내용으로 하는 내용증명을 발송합니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 15 조 (민사상 손해배상 청구)</h2>\n        <p>① 회사는 침해 행위로 인해 발생한 영업상 손실, 브랜드 가치 하락, 미래 기대 수익의 상실 등에 대하여 침해자에게 손해배상을 청구합니다.</p>\n        <p>② 손해배상액은 회사가 입은 실제 손해액뿐만 아니라, 침해자가 얻은 이익액, 또는 통상적으로 받을 수 있는 로열티의 상당액을 포함하여 산정합니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 16 조 (형사 고소)</h2>\n        <p>저작권법 위반(5년 이하의 징역), 부정경쟁방지법 위반, 특허권 침해 등 고의적인 권리 침해 행위에 대해서는 관할 수사기관에 형사 고소를 진행하여 엄중한 처벌을 요구할 것입니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 17 조 (서비스 제공 중지 가처분)</h2>\n        <p>유사 서비스로 인해 회복할 수 없는 손해가 발생할 우려가 있는 경우, 회사는 본안 소송 제기 전이라도 법원에 서비스 제공 금지 가처분을 신청하여 해당 서비스의 운영을 강제로 중단시킬 수 있습니다.</p>\n    </div>\n\n    <div class=\"chapter-title\">제 5 장 기타</div>\n\n    <div class=\"section\">\n        <h2>제 18 조 (면책)</h2>\n        <p>이용자가 서비스 내에 게시한 게시물(조문 메시지 등)에 대한 저작권은 해당 이용자에게 있으며, 회사는 이용자가 게시한 콘텐츠가 제3자의 저작권을 침해하여 발생하는 분쟁에 대해서는 책임을 지지 않습니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 19 조 (침해 신고 및 권리 소명)</h2>\n        <p>① 회사의 지식재산권을 침해하는 사례를 발견하거나, 자신의 저작권이 침해되었다고 판단되는 경우 아래 연락처로 신고해 주시기 바랍니다.</p>\n        <p>담당 부서: 지식재산권 관리 담당</p>\n        <p>연락처: 052-286-4440</p>\n        <p>이메일: kaibcmac@gmail.com</p>\n        <p>② 회사는 신고 접수 후 지체 없이 내용을 확인하고 필요한 조치를 취할 것입니다.</p>\n    </div>\n\n    <div class=\"section\">\n        <h2>제 20 조 (관할 법원)</h2>\n        <p>본 정책과 관련된 지식재산권 분쟁 및 소송은 회사의 본점 소재지를 관할하는 지방법원을 제1심 전속 관할 법원으로 합니다.</p>\n    </div>";
